#include<iostream>
#include<vector>
#include <sstream>
using namespace std;
​
// 找到对应组的组长
int find(int a, vector<int> &ans) {
    // 路径压缩
    if (ans[a] != a) {
        ans[a] = find(ans[a], ans);
    } 
    return ans[a]; 
}
// 通用切割函数 将str 根据 delimiter 进行切割
vector<string> split(const string& str, const string& delimiter) {
    vector<string> result;
    size_t start = 0;
    size_t end = str.find(delimiter);
    while (end != string::npos) {
        result.push_back(str.substr(start, end - start));
        start = end + delimiter.length();
        end = str.find(delimiter, start);
    }
    // 添加最后一个部分
    result.push_back(str.substr(start));
    return result;
}
​
// 合并组
void merge(int a, int b, vector<int> &ans) {
    int rootA = find(a, ans);
    int rootB = find(b, ans);
​
    int newRoot = min(rootA, rootB);
    ans[rootA] = newRoot;
    ans[rootB] = newRoot;
}
​
​
int main() {
    // 接受输入
    string input;
    getline(cin, input);
    vector<string> grid = split(input, ",");
    int n = grid.size();
    // 初始化设置每个组代表为自己
    vector<int> root(n);
    for (int i = 0; i <n ; i++) {
        root[i] = i;
    }
    // 合并处理 因为是对称的只需要处理 左下部分即可
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            // 合并两个组
            if (grid[i][j] == '1') {
                merge(i, j, root);
            }
        }
    }
    // 记录组的数量
    int res = 0;
    for (int i = 0; i <n ; i++) {
        if (find(i, root) == i) {
            res++;
        }
    }
    cout << res;
    return 0;
}
