package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
// 找到对应组的组长 (带路径压缩)
func find(a int, root []int) int {
    if root[a] != a {
        root[a] = find(root[a], root)
    }
    return root[a]
}
​
// 合并组
func merge(a, b int, root []int) {
    rootA := find(a, root)
    rootB := find(b, root)
    newRoot := rootA
    if rootB < rootA {
        newRoot = rootB
    }
    root[rootA] = newRoot
    root[rootB] = newRoot
}
​
func main() {
    in := bufio.NewScanner(os.Stdin)
    in.Scan()
    input := in.Text()
​
    // 接受输入
    grid := strings.Split(input, ",")
    n := len(grid)
​
    // 初始化设置每个组代表为自己
    root := make([]int, n)
    for i := 0; i < n; i++ {
        root[i] = i
    }
​
    // 合并处理 因为是对称的只需要处理左下部分即可
    for i := 0; i < n; i++ {
        for j := 0; j < i; j++ {
            if grid[i][j] == '1' {
                merge(i, j, root)
            }
        }
    }
​
    // 记录组的数量
    res := 0
    for i := 0; i < n; i++ {
        if find(i, root) == i {
            res++
        }
    }
​
    fmt.Println(res)
}
